import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-yuna-host';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;game.startDebugPhase('garden','EASY');for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);
 const report=await evaluate(`(async()=>{
  const {createGardenState,restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');
  const {GARDEN_BEETLES}=await import('/src/js/garden/GardenEncounters.js');
  const {gardenPlatforms,GARDEN_CHECKPOINTS}=await import('/src/js/garden/GardenLevel.js');
  let s=createGardenState('EASY');s.stage='RUNNING';s.checkpoint=GARDEN_CHECKPOINTS.at(-1);s.player.x=GARDEN_BEETLES[2].x-70;s.player.y=590;s.player.support='descanso-final';s.player.terrain='soil';s.safeGround='descanso-final';s.trail=['descanso-final'];phase.state=restoreGardenState(s,'EASY');
  const key=(code,pressed)=>window.dispatchEvent(new KeyboardEvent(pressed?'keydown':'keyup',{code,key:code==='Space'?' ':code,bubbles:true,cancelable:true}));
  let jumping=false,paused=false,restored=false,panicAt=null,endedAt=null,last=null;const intervals=[],clouds=new Set();
  game.setPaused(false);
  const wallStart=performance.now();
  await new Promise((resolve,reject)=>{
   const frame=async now=>{try{
    s=phase.state;if(last!==null)intervals.push(now-last);last=now;
    if(s.stage==='RESCUING'||s.stage==='DISORIENTED')throw Error('Resgate inesperado na travessia manual das nuvens');
    if(s.encounters.panic){
     panicAt??=s.time;
     if(s.player.vx>220.001)throw Error('Medo aumentou velocidade');
     if(s.player.onGround&&s.player.support.startsWith('nuvem-final'))clouds.add(s.player.support);
     if(!paused&&s.encounters.panic.elapsed>1){
      paused=true;game.setPaused(true);const before=JSON.stringify(phase.snapshot());await new Promise(r=>setTimeout(r,350));if(JSON.stringify(phase.snapshot())!==before)throw Error('Pausa avançou relógios');game.setPaused(false);last=null;
     }
     if(!restored&&s.encounters.panic.elapsed>2){restored=true;const save=phase.snapshot().state;phase.state=restoreGardenState(save,'EASY');s=phase.state;}
    }else if(panicAt!==null)endedAt??=s.time;
    key('ArrowRight',!s.encounters.panic);key('ArrowLeft',Boolean(s.encounters.panic));
    const support=gardenPlatforms(s.time,s,s.player.x,600).find(p=>p.id===s.player.support);
    if(s.player.onGround){if(jumping){jumping=false;}else if(support&&support.x+support.w-s.player.x<34){jumping=true;}}
    key('Space',jumping);
    phase.render();
    if(s.stage==='COMPLETE'){resolve();return;}
    if(now-wallStart>24000)throw Error('Gameplay manual não concluiu: '+JSON.stringify(s.player));
    requestAnimationFrame(frame);
   }catch(error){reject(error);}};requestAnimationFrame(frame);
  });
  key('ArrowRight',false);key('ArrowLeft',false);key('Space',false);game.setPaused(true);
  if(clouds.size!==4)throw Error('Nem todas as nuvens foram pisadas durante perseguição: '+[...clouds]);
  if(!paused||!restored||endedAt===null)throw Error('Pausa, restore ou término não exercitados');
  const sorted=intervals.filter(x=>x<100).sort((a,b)=>a-b),at=q=>sorted[Math.min(sorted.length-1,Math.floor(sorted.length*q))];
  return{resultado:'gameplay real do checkpoint final até o piquenique, por teclado e RAF',nuvens:[...clouds],pausa:paused,restoreDuranteMedo:restored,duracaoObservada:endedAt-panicAt,rafP95:at(.95),rafP99:at(.99),amostras:intervals.length,final:phase.state.stage};
 })()`);console.log(JSON.stringify(report));
 for(const [name,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:name!=='desktop'});
  const data=await evaluate(`(()=>{phase.state.stage='COMPLETE';phase.state.age=22;phase.render();return phase.canvas.toDataURL();})()`);await writeFile(out+'/'+name+'-host.png',Buffer.from(data.split(',')[1],'base64'));
 }
 await writeFile('docs/diario-ia/qa-resultados/yuna/host.json',JSON.stringify(report,null,2));

}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
